// Successful Waves is an exploration of waves that are successful
// They propagate in many different ways
// They are successful in all possible ways

amt_code = 100%;

s = save;

d = toggles drawing; // on by default. click on the screen.

SuccessfulWaves.FitToScreen(); // reload to fit new screen size

url params = {
	”w” = width ;
	“h” = height;
	// Specify the canvas size in the url for outputting custom dimensions.
	// eg: /?w=1920&h=1080
}

